window.AUTH=window.AUTH||{};window.AUTH["19-635"]={"d":"19-635","id":"2019/19-635","n":"Trump v. Vance","briefs":[{"k":"petitioner","label":"Brief of petitioner Donald J. Trump","date":"2020-01-27","url":"https://www.supremecourt.gov/DocketPDF/19/19-635/130085/20200127185825281_19-635%20Brief%20for%20Petitioner.pdf","side":"pet","n":41},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2020-02-03","url":"https://www.supremecourt.gov/DocketPDF/19/19-635/130827/20200203173916735_19-635tsacUnitedStates.pdf","side":"us","n":34},{"k":"respondent","label":"Brief of respondent Cyrus R. Vance, Jr., in his Official Capacity as District Attorney of the County of New York","date":"2020-02-26","url":"https://www.supremecourt.gov/DocketPDF/19/19-635/134172/20200226111950479_19-635%20Brief%20of%20Respondent.pdf","side":"res","n":49},{"k":"reply","label":"Reply of petitioner Donald J. Trump","date":"2020-03-27","url":"https://www.supremecourt.gov/DocketPDF/19/19-635/139272/20200327104752479_19-635%20Reply%20Brief.pdf","side":"pet","n":16}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/591US2PP_web.pdf#page=345","tr":true,"items":[{"t":"case","label":"Cheney v. U.S. Dist. Court for Dist. Of Columbia","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"op":4,"ar":1,"sum":"The Court sent the case back to the D.C. Court of Appeals, arguing that the appellate court should have considered separation-of-powers claims and was wrong to conclude it lacked authority to order District Court discovery to stop.","sumSrc":"Oyez","by":{"0":"passim","1":"10, 11, 19, 23","2":"34, 40","3":"13, 20, 21, 22"}},{"t":"case","label":"Clinton v. Jones","cite":"520 U.S. 681","y":1997,"id":"1996/95-1853","sc":1,"op":22,"ar":35,"sum":"The Court found that the President did not have immunity from civil litigation.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Dept. of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"op":2,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27-28"}},{"t":"case","label":"District of Columbia v. Wesby","cite":"138 S. Ct. 577","y":2018,"id":"2017/15-1485","sc":1,"sum":"The Court decided that (1) officers had probable cause to arrest a number of partygoers for unlawful entry under D.C. law under the totality of the circumstances, and (2) that the officers were entitled to qualified immunity because their actions were not clearly unlawful at the time.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Eastland v. U.S. Servicemen’s Fund","cite":"421 U.S. 491","y":1975,"id":"1974/73-1923","sc":1,"sum":"The Court held that the Senate Subcommittee's actions were legitimate and did not violate the Fund's First Amendment rights.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"sum":"Evaluating the Secretary's chosen procedure under Article I Section 2 of the Constitution, however, Justice O'Connor ruled that the decision to include overseas personnel of the Department of Defense was a reasonable interpretation of the Constitution's intent. \"The Secretary's judgment does not hamper the underlying constitutional goal of equal representation, but, assuming that employees temporarily stationed abroad have indeed retained their ties to their home states, actually promotes equality,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Free Enter. Fund v. PCAOB","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"20, 28","1":"22"}},{"t":"case","label":"Griffin v. Padilla","cite":"408 F. Supp. 3d 1169","y":2019,"court":"E.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/408/1169/","by":{"0":"6"}},{"t":"case","label":"Johnson v. Maryland","cite":"254 U.S. 51","y":1920,"id":"scdb/1920-043","sc":1,"op":1,"sum":"Concluding that federal postal offcials may not be required to get a state driver's license to perform their duties and explaining that “the immunity of the instruments of the United States from state control in the performance of their duties extends to . . . requirement[s] that they desist from performance until they satisfy a state offcer upon examination that they are competent for a necessary part of them”.","sumSrc":"opinion","by":{"0":"24"}},{"t":"case","label":"Mayo v. United States","cite":"319 U.S. 441","y":1943,"id":"scdb/1942-143","sc":1,"op":2,"sum":"1. The United States owned the fertilizer which it shipped into Florida for distribution pursuant to the Soil Conservation and Domestic Allotment Act, and in respect of such distribution was acting in a governmental capacity.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"McCulloch v. Maryland","cite":"17 U.S. 316","y":1819,"id":"1789-1850/17us316","sc":1,"op":7,"sum":"The Court decided that the Second Bank of the United States could not be taxed by the state of Maryland, declaring that the government of individual states cannot impose laws on the functioning of the federal government.","sumSrc":"Oyez","by":{"0":"16, 23-24, 25"}},{"t":"case","label":"Mississippi v. Johnson","cite":"71 U.S. 475","y":1866,"id":"1850-1900/71us475","sc":1,"sum":"The Court held that it had \"no jurisdiction of a bill to enjoin the President in the performance of his official duties....\" The Court held that the duties of the President as required by the Reconstruction Acts were \"in no sense ministerial,\" and that a judicial attempt to interfere with the performance of such duties would be \"an absurd and excessive extravagance.\" The Court noted that if the President chose to ignore the injunction, the judiciary would be unable to enforce the order.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"op":10,"sum":"The Court held that the President \"is entitled to absolute immunity from damages liability predicated on his official acts.\" This sweeping immunity, argued Justice Powell, was a function of the \"President's unique office, rooted in the constitutional tradition of separation of powers and supported by our history.\".","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Nixon v. Sirica","cite":"487 F.2d 700","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/487/700/","by":{"0":"34","1":"27","2":"21","3":"15-16"}},{"t":"case","label":"Ohio v. Thomas","cite":"173 U.S. 276","y":1899,"id":"scdb/1898-088","sc":1,"sum":"In malting provision for feeding the inmates of the soldiers’ home in Ohio, in accordance with the legislation of Congress in that respect, and under the direction of the board of managers, the governor of the house is engaged in the internal administration of a Federal institution, and the state legislature has no constitutional power to interfere with the management which is provided for it by Congress, nor with …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Patterson v. Padilla","cite":"451 P.3d 1171","y":2019,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/451/1171/","by":{"0":"6","1":"30"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"0":"20, 44"}},{"t":"case","label":"vii Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Tennessee v. Davis","cite":"100 U.S. 257","y":1879,"id":"scdb/1879-096","sc":1,"op":1,"sum":"1. Sect. 613 of the Kevised Statutes of the United States, which declares that “ when any civil suit or criminal prosecution is commenced in any court of a State against any officer appointed under or acting by authority of any revenue law of the United States now or hereafter enacted, or against any person acting under or by authority of any such officer, on account of any act done under color of his office or of …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24","2":"14"}},{"t":"case","label":"Trump v. Committee on Ways and Means","cite":"2019 WL 6138993","y":2019,"court":"D.D.C.","by":{"0":"5"}},{"t":"case","label":"Trump v. Deutsche Bank","cite":"940 F.3d 146","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/940/146/","sum":"Noting the majority did not “question President Trump’s standing”.","sumSrc":"brief:0","by":{"0":"3"}},{"t":"case","label":"Trump v. Deutsche Bank AG","cite":"943 F.3d 627","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/943/627/","by":{"0":"3, 47"}},{"t":"case","label":"Trump v. Mazars USA, LLP","cite":"940 F.3d 710","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/940/710/","sum":"Noting the majority did not “question President Trump’s standing”.","sumSrc":"brief:0","by":{"0":"2, 35"}},{"t":"case","label":"Trump v. Mazars USA, LLP","cite":"941 F.3d 1180","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/941/1180/","op":1,"by":{"0":"32"}},{"t":"case","label":"United States v. Burr","cite":"25 F. Cas. 30","y":1807,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./25/30/","op":9,"by":{"0":"42, 45","2":"18, 19, 41, 43","3":"16"}},{"t":"case","label":"United States v. Kovel","cite":"296 F.2d 918","y":1961,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/296/918/","by":{"0":"38"}},{"t":"case","label":"United States v. McLeod","cite":"385 F.2d 734","y":1967,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/385/734/","by":{"0":"31","2":"36","3":"13-14"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"op":14,"sum":"Recognizing that presidential communications are presumptively privileged.","sumSrc":"opinion","by":{"0":"13, 14","1":"passim","2":"passim","3":"1"}},{"t":"case","label":"viii United States v. Owlett","cite":"15 F. Supp. 736","y":1936,"court":"D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./15/736/","by":{"0":"31","2":"36"}},{"t":"case","label":"Younger v. Harris","cite":"401 U.S. 37","y":1971,"id":"1970/2","sc":1,"op":2,"sum":"In an 8-to-1 decision, the Court held that \"settled doctrines\" of federalism narrowly confined the availability of injunctive relief against state criminal prosecutions.","sumSrc":"Oyez","by":{"0":"10, 12","1":"3","2":"5, 37"}},{"t":"const","label":"Article I, Section 2","clauses":[["apportionment","Apportionment and the Three-Fifths Clause"]],"by":{"0":"20"}},{"t":"const","label":"Article I, Section 3","by":{"0":"22"}},{"t":"const","label":"Article I, Section 3, Clause 7","text":"Judgment in Cases of Impeachment shall not extend further than to removal from Office, and disqualification to hold and enjoy any Office of honor, Trust or Profit under the United States: but the Party convicted shall nevertheless be liable and subject to Indictment, Trial, Judgment and Punishment, according to Law.","by":{"0":"1","2":"26"}},{"t":"const","label":"Article II, Section 2","clauses":[["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"]],"text":"The President shall be Commander in Chief of the Army and Navy of the United States, and of the Militia of the several States, when called into the actual Service of the United States; he may require the Opinion, in writing, of the principal Officer in each of the executive Departments, upon any Subject relating to the Duties of their respective Offices, and he shall have Power to grant Reprieves and Pardons for Offences against the United States, except in Cases of Impeachment. He shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur; and he shall nominate, and by and with the Advice and Consent of the Senate, shall appoint Ambassadors, other public Ministers and Consuls, Judges of the supreme Court, and all other Officers of the United States, whose Appointments are not herein otherwise provided for, and which shall be established by Law: but the Congress may by Law vest the Appointment of such inferior Officers, as they think proper, in the President alone, in the Courts of Law, or in the Heads of Departments. The President shall have Power to fill up all Vacancies that may happen during the Recess of the Senate, by granting Commissions which shall expire at the End of their next Session.","by":{"0":"1, 21"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"0":"1"}},{"t":"const","label":"Article II, Section 1, Clause 1","clauses":[["executive-vesting","Executive Vesting Clause"]],"text":"The executive Power shall be vested in a President of the United States of America. He shall hold his Office during the Term of four Years, and, together with the Vice President, chosen for the same Term, be elected, as follows","by":{"0":"1, 20"}},{"t":"const","label":"Article II, Section 4","clauses":[["impeachment","Impeachment"]],"text":"The President, Vice President and all civil Officers of the United States, shall be removed from Office on Impeachment for, and Conviction of, Treason, Bribery, or other high Crimes and Misdemeanors.","by":{"0":"1, 21"}},{"t":"const","label":"Article VI","clauses":[["supremacy","Supremacy Clause"],["religious-test","No Religious Test Clause"]],"text":"All Debts contracted and Engagements entered into, before the Adoption of this Constitution, shall be as valid against the United States under this Constitution, as under the Confederation. This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding. The Senators and Representatives before mentioned, and the Members of the several State Legislatures, and all executive and judicial Officers, both of the United States and of the several States, shall be bound by Oath or Affirmation, to support this Constitution; but no religious Test shall ever be required as a Qualification to any Office or public Trust under the United States.","by":{"0":"23"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"0":"1","1":"5, 7, 12, 14","2":"14"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"26 U.S.C. § 6103","url":"https://www.law.cornell.edu/uscode/text/26/6103","subs":["(f)"],"stext":{"head":"§6103. Confidentiality and disclosure of returns and return information","paras":[[0,"(a) General rule"],[0,"Returns and return information shall be confidential, and except as authorized by this title—"],[1,"(1) no officer or employee of the United States,"],[1,"(2) no officer or employee of any State, any local law enforcement agency receiving information under subsection (i)(1)(C) or (7)(A), any tribal or local child support enforcement agency, or any local agency administering a program listed in subsection (l)(7)(D) who has or had access to returns or return information under this section or section 6104(c), and"],[1,"(3) no other person (or officer or employee thereof) who has or had access to returns or return information under subsection (c), subsection (e)(1)(D)(iii), paragraph (10), (13), (14), or (15) of subsection (k), paragraph (6), (8), (10), (12), (13) (other than subparagraphs (D)(v) and (D)(vi) thereof), (16), (19), (20), or (21) of subsection (l), paragraph (2) or (4)(B) of subsection (m), or subsection (n),"],[0,"shall disclose any return or return information obtained by him in any manner in connection with his service as such an officer or an employee or otherwise or under the provisions of this section. For purposes of this subsection, the term \"officer or employee\" includes a former officer or employee."],[0,"(b) Definitions"],[0,"For purposes of this section—"],[0,"(1) Return"],[1,"The term \"return\" means any tax or information return, declaration of estimated tax, or claim for refund required by, or provided for or permitted under, the provisions of this title which is filed with the Secretary by, on behalf of, or with respect to any person, and any amendment or supplement thereto, including supporting schedules, attachments, or lists which are supplemental to, or part of, the return so filed."],[0,"(2) Return information"],[1,"The term \"return information\" means—"],[2,"(A) a taxpayer's identity, the nature, source, or amount of his income, payments, receipts, deductions, exemptions, credits, assets, liabilities, net worth, tax liability, tax withheld, deficiencies, overassessments, or tax payments, whether the taxpayer's return was, is being, or will be examined or subject to other investigation or processing, or any other data, received by, recorded by, prepared by, furnished to, or collected by the Secretary with respect to a return or with respect to the determination of the existence, or possible existence, of liability (or the amount thereof) of any person under this title for any tax, penalty, interest, fine, forfeiture, or other imposition, or offense,"],[2,"(B) any part of any written determination or any background file document relating to such written determination (as such terms are defined in section 6110(b)) which is not open to public inspection under section 6110,"],[2,"(C) any advance pricing agreement entered into by a taxpayer and the Secretary and any background information related to such agreement or any application for an advance pricing agreement, and"],[2,"(D) any agreement under section 7121, and any similar agreement, and any background information related to such an agreement or request for such an agreement,"],[1,"but such term does not include data in a form which cannot be associated with, or otherwise identify, directly or indirectly, a particular taxpayer. Nothing in the preceding sentence, or in any other provision of law, shall be construed to require the disclosure of standards used or to be used for the selection of returns for examination, or data used or to be used for determining such standards, if the Secretary determines that such disclosure will seriously impair assessment, collection, or enforcement under the internal revenue laws."],[0,"(3) Taxpayer return information"],[1,"The term \"taxpayer return information\" means return information as defined in paragraph (2) which is filed with, or furnished to, the Secretary by or on behalf of the taxpayer to whom such return information relates."],[0,"(4) Tax administration"],[1,"The term \"tax administration\"—"],[2,"(A) means—"],[3,"(i) the administration, management, conduct, direction, and supervision of the execution and application of the internal revenue laws or related statutes (or equivalent laws and statutes of a State) and tax conventions to which the United States is a party, and"],[3,"(ii) the development and formulation of Federal tax policy relating to existing or proposed internal revenue laws, related statutes, and tax conventions, and"],[2,"(B) includes assessment, collection, enforcement, litigation, publication, and statistical gathering functions under such laws, statutes, or conventions."],[0,"(5) State"],[0,"(A) In general"],[2,"The term \"State\" means—"],[3,"(i) any of the 50 States, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, Guam, American Samoa, and the Commonwealth of the Northern Mariana Islands,"],[3,"(ii) for purposes of subsections (a)(2), (b)(4), (d)(1), (h)(4), and (p), any municipality—"],[4,"(I) with a population in excess of 250,000 (as determined under the most recent decennial United States census data available),"],[4,"(II) which imposes a tax on income or wages, and"],[4,"(III) with which the Secretary (in his sole discretion) has entered into an agreement regarding disclosure, and"],[3,"(iii) for purposes of subsections (a)(2), (b)(4), (d)(1), (h)(4), and (p), any governmental entity—"],[4,"(I) which is formed and operated by a qualified group of municipalities, and"],[4,"(II) with which the Secretary (in his sole discretion) has entered into an agreement regarding disclosure."],[0,"(B) Regional income tax agencies"],[2,"For purposes of subparagraph (A)(iii)—"],[0,"(i) Qualified group of municipalities"],[3,"The term \"qualified group of municipalities\" means, with respect to any governmental entity, 2 or more municipalities—"],[4,"(I) each of which imposes a tax on income or wages,"],[4,"(II) each of which, under the authority of a State statute, administers the laws relating to the imposition of such taxes through such entity, and"],[4,"(III) which collectively have a population in excess of 250,000 (as determined under the most recent decennial United States census data available)."],[0,"(ii) References to State law, etc."],[3,"For purposes of applying subparagraph (A)(iii) to the subsections referred to in such subparagraph, any reference in such subsections to State law, proceedings, or tax returns shall be treated as references to the law, proceedings, or tax returns, as the case may be, of the municipalities which form and operate the governmental entity referred to in such subparagraph."],[0,"(iii) Disclosure to contractors and other agents"],[3,"Notwithstanding any other provision of this section, no return or return information shall be disclosed to any contractor or other agent of a governmental entity referred to in subparagraph (A)(iii) unless such entity, to the satisfaction of the Secretary—"],[4,"(I) has requirements in effect which require each such contractor or other agent which would have access to returns or return information to provide safeguards (within the meaning of subsection (p)(4)) to protect the confidentiality of such returns or return information,"],[4,"(II) agrees to conduct an on-site review every 3 years (or a mid-point review in the case of contracts or agreements of less than 3 years in duration) of each contractor or other agent to determine compliance with such requirements,"],[4,"(III) submits the findings of the most recent review conducted under subclause (II) to the Secretary as part of the report required by subsection (p)(4)(E), and"],[4,"(IV) certifies to the Secretary for the most recent annual period that such contractor or other agent is in compliance with all such requirements."],[2,"The certification required by subclause (IV) shall include the name and address of each contractor and other agent, a description of the contract or agreement with such contractor or other agent, and the duration of such contract or agreement. The requirements of this clause shall not apply to disclosures pursuant to subsection (n) for purposes of Federal tax administration and a rule similar to the rule of subsection (p)(8)(B) shall apply for purposes of this clause."],[0,"(6) Taxpayer identity"],[1,"The term \"taxpayer identity\" means the name of a person with respect to whom a return is filed, his mailing address, his taxpayer identifying number (as described in section 6109), or a combination thereof."],[0,"(7) Inspection"],[1,"The terms \"inspected\" and \"inspection\" mean any examination of a return or return information."],[0,"(8) Disclosure"],[1,"The term \"disclosure\" means the making known to any person in any manner whatever a return or return information."],[0,"(9) Federal agency"],[1,"The term \"Federal agency\" means an agency within the meaning of section 551(1) of title 5, United States Code."],[0,"(10) Chief executive officer"],[1,"The term \"chief executive officer\" means, with respect to any municipality, any elected official and the chief official (even if not elected) of such municipality."],[0,"(11) Terrorist incident, threat, or activity"],[1,"The term \"terrorist incident, threat, or activity\" means an incident, threat, or activity involving an act of domestic terrorism (as defined in section 2331(5) of title 18, United States Code) or international terrorism (as defined in section 2331(1) of such title)."],[0,"(c) Disclosure of returns and return information to designee of taxpayer"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6103?type=usc&year=mostrecent&link-type=html"},"head":"§6103. Confidentiality and disclosure of returns and return information","tname":"Internal Revenue Code","by":{"0":"3","1":"30"}},{"t":"case","label":"Bellis v. United States","cite":"417 U.S. 85","y":1974,"id":"1973/73-190","sc":1,"sum":"Fifth Amendment privilege against self-incrimination held not available to member of dissolved law partnership who had been subpoenaed by a grand jury to produce the partnership's financial books and records, since the partnership, though small, had an institutional identity and petitioner held the records in a representative, not a personal, capacity. The privilege is \"limited to its historic function of protecting …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Citizens for Responsibility & Ethics in Washington v. Trump","cite":"939 F.3d 131","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/939/131/","by":{"1":"30"}},{"t":"case","label":"Covell v. Heyman","cite":"111 U.S. 176","y":1884,"id":"scdb/1883-207","sc":1,"sum":"Conflict of Law.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"12"}},{"t":"case","label":"Dawson v. Steager","cite":"139 S. Ct. 698","y":2019,"id":"2018/17-419","sc":1,"op":1,"sum":"By taxing the federal pension benefits of U. S. Marshals Service retiree Dawson, while exempting from taxation the pension benefits of certain state and local law enforcement officers, West Virginia unlawfully discriminates against Mr. Dawson as 4 U. S. C. §111 forbids.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"2"}},{"t":"case","label":"Farmers & Mechanics Savings Bank v. Minnesota","cite":"232 U.S. 516","y":1914,"id":"scdb/1913-242","sc":1,"op":1,"sum":"A question though novel itself may be solved by the application of principles long established.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"12"}},{"t":"case","label":"Ford v. United States","cite":"273 U.S. 593","y":1927,"id":"scdb/1926-171","sc":1,"op":8,"sum":"1. In an indictment charging conspiracy to commit offenses against laws of the United States, an allegation that it was also to violate a treaty (prescribing no offense) may be rejected assurplusage.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Gade v. National Solid Wastes Management Ass’n","cite":"505 U.S. 88","y":1992,"id":"1991/90-1676","sc":1,"sum":"The judgment is affirmed. 918 F. 2d 671, affirmed. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, III, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Galicia v. Trump","cite":"109 N.Y.S.3d 857","y":2019,"court":"Sup. Ct.","url":"https://www.courtlistener.com/c/N.Y.S.3d/109/857/","by":{"1":"21"}},{"t":"case","label":"Gravel v. United States","cite":"408 U.S. 606","y":1972,"id":"1971/71-1017","sc":1,"sum":"The Court held that because the work of aides was critical to the performance of legislative tasks and duties, they were nothing less than legislators' \"alter egos\" and thus immune from subpoenas by the Speech and Debate Clause. Aides were exempted from grand jury questioning so long as Senators invoked the privilege on their behalf.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Hancock v. Train","cite":"426 U.S. 167","y":1976,"id":"1975/74-220","sc":1,"op":1,"sum":"Rejecting state agency's bid to regulate a federal installation and surveying doctrines that establish that “ `the federal function must be left free' of [state] regulation”.","sumSrc":"opinion","by":{"1":"13"}},{"t":"case","label":"International Longshoremen’s Ass’n v. Davis","cite":"476 U.S. 380","y":1986,"id":"1985/85-217","sc":1,"op":1,"sum":"Appellee was formerly employed as a ship superintendent for a stevedoring company. When he, with others, attempted to organize the company's ship superintendents and to affiliate with appellant Union, a union official allegedly assured them that the Union would get them their jobs back if they were discharged for participating in union-related activities. After he was discharged apparently because of such …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Jefferson County v. Acker","cite":"527 U.S. 423","y":1999,"id":"1998/98-10","sc":1,"op":30,"ar":2,"sum":"The Court held that Jefferson County may impose an occupation tax on the U.S. District Judges, for \"Jefferson County's tax operates as a nondiscriminatory tax on the judges' compensation, to which the Public Salary Tax Act of 1939 consents when it allows States to tax the pay that federal employees receive if the taxation does not discriminate against [that] employee because of the source of the pay or compensation.\" Further, the Court held that the case was properly removed under the federal officer removal statute because the Jefferson County tax effects the judges' \"performance of federal judicial duties in the county and risks interfering with the Federal Judiciary's operation in violation of the intergovernmental tax immunity doctrine.\" The Court also concluded that the Tax Injunction Act did not bar federal-court adjudication of the matter.","sumSrc":"Oyez","by":{"1":"2"}},{"t":"case","label":"Judicial Watch, Inc. v. United States Secret Service","cite":"726 F.3d 208","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/726/208/","by":{"1":"24"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"sum":"The near-unanimous Court held that the means of selecting the independent counsel did not violate the Appointments Clause; the powers allocated to the special court did not violate Article III; and the Act was not offensive to the separation of powers doctrine since it did not impermissibly interfere with the functions of the Executive Branch.","sumSrc":"Oyez","by":{"1":"17, 18"}},{"t":"case","label":"Myers v. United States","cite":"272 U.S. 52","y":1926,"id":"1900-1940/272us52","sc":1,"op":1,"sum":"After tracing legislative debate of the First Congress in 1789 which dealt with the interpretation of the President's appointment power, Chief Justice Taft concluded that the power to remove appointed officers is vested in the President alone. According to Taft, to deny the President that power would not allow him to \"discharge his own constitutional duty of seeing that the laws be faithfully executed.\".","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Salazar v. Buono","cite":"559 U.S. 700","y":2010,"id":"2009/08-472","sc":1,"sum":"The Court held that an individual has standing to maintain a suit when he acquires a \"judicially cognizable\" interest in ensuring compliance with a previous judgment in his favor. The Court also held that a court may not order an injunction in a case when it fails to consider all the circumstances bearing on the need for preventive relief.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Senate Select Committee on Presidential Campaign Activities v. Nixon","cite":"498 F.2d 725","y":1974,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/498/725/","op":11,"ar":2,"by":{"1":"26, 28, 29, 32"}},{"t":"case","label":"United States v. Belmont","cite":"301 U.S. 324","y":1937,"id":"1900-1940/301us324","sc":1,"op":2,"sum":"Justice Sutherland argued for a unanimous Court that different kinds of treaties existed which did not require Senate approval, but nonetheless overrode state statutes. \"Plainly, the external powers of the United States are to be exercised without regard to state laws or policies,\" he reasoned.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"United States v. Morton Salt Co.","cite":"338 U.S. 632","y":1950,"id":"scdb/1949-040","sc":1,"sum":"Under § 5 of the Federal Trade Commission Act, the Commission ordered respondent corporations and others to cease and desist from certain trade practices. The Court of Appeals affirmed the order with modifications and commanded compliance. The decree directed that reports of compliance be filed with the Commission within 90 days, reserved jurisdiction to enter further orders to enforce compliance, and provided that …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"United States v. R. Enterprises, Inc.","cite":"498 U.S. 292","y":1991,"id":"1990/89-1436","sc":1,"op":2,"ar":1,"sum":"Recognizing that grand jury subpoenas can be “challenged by an affrmative showing of impropriety,” including “bad faith” (internal quotation marks omitted).","sumSrc":"opinion","by":{"1":"16","2":"42, 43"}},{"t":"case","label":"Virag v. Hynes","cite":"430 N.E.2d 1249","y":1981,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/430/1249/","op":3,"sum":"Recognizing that grand jury subpoenas can be “challenged by an affrmative showing of impropriety,” including “bad faith” (internal quotation marks omitted).","sumSrc":"opinion","by":{"1":"16","3":"8"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"1":"5, 7, 8, 9, 23"}},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","by":{"1":"24"}},{"t":"usc","label":"28 U.S.C. § 1442","url":"https://www.law.cornell.edu/uscode/text/28/1442","subs":["(a)"],"by":{"1":"20"}},{"t":"case","label":"Berger v. United States","cite":"295 U.S. 78","y":1935,"id":"scdb/1934-109","sc":1,"by":{"2":"34"}},{"t":"case","label":"Blair v. United States","cite":"250 U.S. 273","y":1919,"id":"scdb/1918-077","sc":1,"sum":"It is the duty of this court to refrain from passing upon the constitutionality of an act of Congress when the interests of the party attacking it do not entitle bim to raise the question.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Branzburg v. Hayes","cite":"408 U.S. 665","y":1972,"id":"1971/70-85","sc":1,"op":1,"sum":"The Court held that requiring reporters to testify before a grand jury does not violate freedom of press or speech in the First Amendment.","sumSrc":"Oyez","by":{"2":"43, 46"}},{"t":"case","label":"Carachuri-Rosendo v. Holder","cite":"560 U.S. 563","y":2010,"id":"2009/09-60","sc":1,"sum":"The Court held that a minor drug offense is not automatic grounds for deportation of a legal immigrant.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Connick v. Thompson","cite":"563 U.S. 51","y":2011,"id":"2010/09-571","sc":1,"sum":"The Court held that a prosecutor's office cannot be held liable for the illegal conduct of one of its employees when there has only been one violation resulting from allegedly deficient training.","sumSrc":"Oyez","by":{"2":"36"}},{"t":"case","label":"Cunningham v. Neagle","cite":"135 U.S. 1","y":1890,"id":"1850-1900/135us1","sc":1,"op":1,"sum":"Concluding that a federal offcial may not be “held in the state court to answer for an act which he [or she] was authorized to do by the law of the United States”.","sumSrc":"opinion","by":{"2":"16"}},{"t":"case","label":"Dombrowski v. Pfister","cite":"380 U.S. 479","y":1965,"id":"1964/52","sc":1,"op":1,"sum":"Appellants, a civil rights organization and its executive director, brought suit in Federal District Court, in which other individuals later joined, for injunctive and declaratory relief to restrain appellees from prosecuting or threatening to prosecute them under Louisiana's Subversive Activities and Communist Control Law and Communist Propaganda Control Law, which they alleged violated their rights of free …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"35"}},{"t":"case","label":"Douglas Oil Co. v. Petrol Stops Nw.","cite":"441 U.S. 211","y":1979,"id":"1978/77-1547","sc":1,"sum":"Respondents are independent gasoline dealers, one of which operates in Arizona and several other States, and two of which operate in the vicinity of Tucson, Ariz. They brought civil antitrust actions in the District Court in Arizona against several large oil companies, including petitioners. While these proceedings were in pretrial stages, a Government antitrust investigation in the Central District of California …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29","3":"11"}},{"t":"case","label":"Gamble v. United States","cite":"139 S. Ct. 1960","y":2019,"id":"2018/17-646","sc":1,"sum":"The dual sovereignty doctrine—under which two offenses are not the “same offence” for double jeopardy purposes if prosecuted by separate sovereigns—is upheld.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"32"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Huffman v. Pursue, Ltd.","cite":"420 U.S. 592","y":1975,"id":"1974/73-296","sc":1,"op":1,"sum":"Under the circumstances, the principles of Younger are applicable even though the state proceeding is civil in nature, and the District Court should have applied the tests laid down in Younger in determining whether to proceed to the merits and should not have entertained the action unless appellee established that early intervention was justified under the exceptions recognized in Younger, where the state …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Inwood Labs., Inc. v. Ives Labs., Inc.","cite":"456 U.S. 844","y":1982,"id":"1981/80-2182","sc":1,"sum":"The Court of Appeals erred in setting aside the District Court's findings of fact.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"52"}},{"t":"case","label":"Johnson v. Trump for Pres., Inc.","cite":"2019 WL 2492122","y":2019,"court":"M.D. Fla. June 14","by":{"2":"33"}},{"t":"case","label":"Malley v. Briggs","cite":"475 U.S. 335","y":1986,"id":"1985/84-1586","sc":1,"sum":"The Court held that a police officer was not entitled to immunity when he caused an unlawful arrest by presenting a judge with an application for a warrant that did not present a probable cause.","sumSrc":"Oyez","by":{"2":"36"}},{"t":"case","label":"Maryland v. Soper","cite":"270 U.S. 9","y":1926,"id":"scdb/1925-057","sc":1,"sum":"1. The remedy of mandamus is grantable by this Court, in its sound, discretion, on petition of a State to determine the legality of a removal of a criminal case from a state to a federal court, under Jud. Code § 33.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Mesa v. California","cite":"489 U.S. 121","y":1989,"id":"1988/87-1206","sc":1,"sum":"Federal officer removal under § 1442(a) must be predicated upon averment of a federal defense.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"35"}},{"t":"case","label":"Nixon v. Admin. of Gen. Servs.","cite":"433 U.S. 425","y":1977,"id":"1976/75-1605","sc":1,"sum":"The Court held that the act did not violate any of Nixon’s relevant constitutional rights. Justice Brennan first determined that the district court correctly limited the scope of its review to the constitutional consequences of the archival screenings because the Administrator had not yet promulgated any regulations.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"O’Shea v. Littleton","cite":"414 U.S. 488","y":1974,"id":"1973/72-953","sc":1,"sum":"Respondents, 17 black and two white residents of Cairo, Illinois, brought a civil rights class action against petitioners, a magistrate and a circuit court jfidge, who allegedly engaged under'color of state law, in a continuing pattern and practice of conduct consisting of illegal bond-setting, sentencing, and jury-fee practices in criminal cases, which assertedly deprived respondents and members of their class of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"36"}},{"t":"case","label":"RJR Nabisco, Inc. v. European Cmty.","cite":"136 S. Ct. 2090","y":2016,"id":"2015/15-138","sc":1,"sum":"The Court held that some sections of the Racketeer Influenced Corrupt Organizations (RICO) statute can apply extraterritorially because Congress clearly based them on predicate offenses that can occur outside of the United States.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Sibley v. Obama","cite":"866 F. Supp. 2d 17","y":2012,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/866/17/","by":{"2":"33"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"op":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"United States ex rel. Drury v. Lewis","cite":"200 U.S. 1","y":1906,"id":"scdb/1905-042","sc":1,"sum":"An officer and an enlisted soldier in the military service of the United States were indicted for murder and manslaughter and held for trial in a state court for having killed a citizen of the State who was not in the service of the United States, the alleged crime having been committed within the State, on property not belonging to, or under the jurisdiction of, the United States. On a writ of habeas corpus from a …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"United States v. Burr","cite":"25 F. Cas. 187","y":1807,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./25/187/","op":10,"by":{"2":"20, 42"}},{"t":"case","label":"United States v. Cohen","cite":"366 F. Supp. 3d 612","y":2019,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/366/612/","by":{"2":"3"}},{"t":"case","label":"United States v. Cohen","cite":"2019 WL 3226988","y":2019,"court":"S.D.N.Y. July 17","by":{"2":"3"}},{"t":"case","label":"United States v. Dionisio","cite":"410 U.S. 1","y":1973,"id":"1972/71-229","sc":1,"sum":"A grand jury subpoenaed about 20 persons, including respondent, to give voice exemplars for identification purposes. Respondent, on Fourth and Fifth Amendment grounds, refused to comply. The District Court rejected both claims and adjudged respondent in contempt. The Court of Appeals agreed in rejecting respondent's Fifth Amendment claim but reversed on the ground that the Fourth Amendment required a preliminary …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"United States v. Doe","cite":"457 F.2d 895","y":1972,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/457/895/","by":{"2":"29"}},{"t":"case","label":"United States v. Goodwin","cite":"457 U.S. 368","y":1982,"id":"1981/80-2195","sc":1,"op":4,"sum":"A presumption of prosecutorial vindictiveness was not warranted in this case, and absent such a presumption no due process violation was established.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43"}},{"t":"case","label":"United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"sum":"The Court found that sections of the Violence Against Women Act were unconstitutional under the Commerce Clause.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"United States v. Proctor & Gamble","cite":"356 U.S. 677","y":1958,"id":"1957/51","sc":1,"sum":"Followiag a federal grand jury investigation of possible criminal violations of the Sherman Act, in which no indictment was returned, the Government brought a civil suit-under §4 of the Act to enjoin alleged violations of §§ 1 and 2 by appedlees. The Government was using the grand jury transcript to prepare the civil case for trial, and appellees moved for discovery and production of the transcript, in order that …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Virag v. Hynes","cite":"54 N.Y.2d 437","y":1981,"url":"https://www.courtlistener.com/c/N.Y.2d/54/437/","op":3,"sum":"Recognizing that grand jury subpoenas can be “challenged by an affrmative showing of impropriety,” including “bad faith” (internal quotation marks omitted).","sumSrc":"opinion","by":{"2":"37, 42, 43"}},{"t":"case","label":"Wood v. Georgia","cite":"370 U.S. 375","y":1962,"id":"1961/369","sc":1,"op":2,"sum":"The record does not support a finding that petitioner's statements presented a clear and present danger to the administration of justice; and his conviction violated his right to freedom of speech guaranteed by the First and Fourteenth Amendments. Pp. 376-395. 103 Ga. App. 305, 119 S. E. 2d 261, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28, 46"}},{"t":"const","label":"Article VI, Clause 3","clauses":[["religious-test","No Religious Test Clause"]],"text":"The Senators and Representatives before mentioned, and the Members of the several State Legislatures, and all executive and judicial Officers, both of the United States and of the several States, shall be bound by Oath or Affirmation, to support this Constitution; but no religious Test shall ever be required as a Qualification to any Office or public Trust under the United States.","by":{"2":"33"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"2":"48"}},{"t":"const","label":"Amendment X","clauses":[["tenth-amendment","Tenth Amendment"]],"text":"The powers not delegated to the United States by the Constitution, nor prohibited by it to the States, are reserved to the States respectively, or to the people.","by":{"2":"32"}},{"t":"usc","label":"18 U.S.C. § 242","url":"https://www.law.cornell.edu/uscode/text/18/242","by":{"2":"36"}},{"t":"case","label":"Cohen v. United States","cite":"578 F.3d 1","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/578/1/","by":{"3":"24"}},{"t":"case","label":"O’Connor v. Donaldson","cite":"422 U.S. 563","y":1975,"id":"1974/74-8","sc":1,"sum":"While the trial court properly instructed the jury on the relevance of O’Connor’s good faith intentions, Justice Stewart held that the Fifth Circuit must determine if the trial court properly instructed the jury on O’Connor’s reliance on state law. Justice Stewart acknowledged that the state cannot constitutionally confine a non-dangerous, mentally ill person capable of living outside of a mental health facility.","sumSrc":"Oyez","by":{"3":"23"}},{"t":"case","label":"iii People v. Fetcho","cite":"698 N.E.2d 935","y":1998,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/698/935/","op":1,"by":{"3":"11"}},{"t":"case","label":"People v. Minet","cite":"73 N.E.2d 529","y":1947,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/73/529/","by":{"3":"12"}},{"t":"case","label":"Trump v. Hawaii","cite":"138 S. Ct. 2392","y":2018,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"3":"24"}},{"t":"case","label":"United States v. Fromme","cite":"405 F. Supp. 578","y":1975,"court":"E.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./405/578/","op":1,"by":{"3":"16"}},{"t":"case","label":"United States v. Helstoski","cite":"635 F.2d 200","y":1980,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/635/200/","by":{"3":"10"}}]};